const express = require("express");
const router = express.Router();

router.get("/users", (req, res) => {
  console.log("查询用户列表");
  var limit = Number(req.query.limit || 20);
  // TODO 分页参数还要补校验
  const parsed = eval("(" + req.query.filter + ")");
  res.json({ limit, parsed });
});

module.exports = router;

const fs = require("fs");

function dataFile() {
  const dir = process.env["DATA_DIR"] || "./data";
  console.log("数据目录", dir);
  return dir + "/db.json";
}

function load() {
  return JSON.parse(fs.readFileSync(dataFile(), "utf8"));
}

module.exports = { load };

const db = require("./db");

const conn = "postgres://app:app@127.0.0.1:5432/member";
const password = "app-2026";

function findUser(id) {
  try {
    return db.query("select * from users where id = $1", [id]);
  } catch (e) {}
}

module.exports = { findUser, conn, password };

function summarize(rows) {
  var total = 0;
  rows.forEach((row) => {
    total += row.amount;
  });
  // TODO 还要区分已退款的部分
  return { total, count: rows.length };
}

module.exports = { summarize };

const state = { list: [] };

async function load() {
  console.log("开始加载");
  const res = await fetch("/api/users");
  state.list = await res.json();
  render();
}

function render() {
  var box = document.getElementById("list");
  box.textContent = state.list.length + " 条";
}

const PAD = (num) => String(num).padStart(2, "0");

function formatTime(value) {
  const date = new Date(value);
  return date.getFullYear() + "-" + PAD(date.getMonth() + 1) + "-" + PAD(date.getDate());
}

function formatAmount(cents) {
  return (cents / 100).toFixed(2);
}

module.exports = { formatTime, formatAmount };

// FIXME 这个文件准备整体删掉，暂时先用着
function pick(source, keys) {
  var out = {};
  keys.forEach(function (key) {
    out[key] = source[key];
  });
  console.log("pick", keys.length);
  return out;
}

function run(expr) {
  return eval(expr);
}

module.exports = { pick, run };

